const canById = (world, id) => world.cans.find((c) => c.id === id);
const waitingOf = (world) => world.cans.filter((c) => c.lit);
const busy = (world) => !!world.task || world.queue.length > 0;

function headAt(world) {
  return { x: world.g.x.x, y: world.g.y.x, pad: L.padRest - world.g.e.x };
}

function canPosition(world, can) {
  if (can.place.at === "held") {
    const h = headAt(world);
    return [h.x, h.y, h.pad - L.can.h];
  }
  if (can.place.at === "lift") return [L.tubes[can.place.tube], L.cupY, can.z];
  if (can.place.at === "tube") return [L.tubes[can.place.tube], L.cupY, L.hidden + 40];
  return seatOf(can.place);
}

const extFor = (seat) => L.padRest - (seat + L.can.h);

function slotsInUrgency(world) {
  const order = [];
  for (const row of ROWS) for (let col = 0; col < L.cols.length; col++) {
    const can = world.cans.find((c) => c.place.at === "slot" && c.place.row === row && c.place.col === col);
    if (can) order.push(can);
  }
  return order;
}

const freeCol = (world, row) => {
  for (let col = 0; col < L.cols.length; col++) if (!world.cans.some((c) => c.place.at === "slot" && c.place.row === row && c.place.col === col)) return col;
  return -1;
};

const over = ([x, y]) => ({ k: "move", x, y });

function pickAndPlace(from, to) {
  const a = seatOf(from);
  const b = seatOf(to);
  return [
    { k: "ext", e: 0 },
    over(a),
    { k: "ext", e: extFor(a[2]) },
    { k: "grab", from },
    { k: "ext", e: 0 },
    over(b),
    { k: "ext", e: extFor(b[2]) },
    { k: "put", to },
    { k: "ext", e: 0 },
  ];
}

function arrive(world, id) {
  const can = canById(world, id);
  if (can.place.at !== "tube") return [];
  const cup = { at: "cup", tube: can.tube };
  const row = "needs";
  const col = freeCol(world, row);
  return [{ k: "ext", e: 0 }, { k: "move", x: PARK[0], y: PARK[1] }, { k: "drop", id }, { k: "wait", s: 0.35 }, ...pickAndPlace(cup, { at: "slot", row, col })];
}

function allow(world, id) {
  const can = canById(world, id);
  if (can.place.at !== "slot" || !can.lit) return [];
  const at = seatOf(can.place);
  const cup = { at: "cup", tube: can.tube };
  const carry = pickAndPlace(can.place, cup);
  return [
    { k: "ext", e: 0 },
    over(at),
    { k: "ext", e: extFor(at[2]) },
    { k: "press", id },
    { k: "wait", s: 0.28 },
    ...carry.slice(3),
    { k: "move", x: PARK[0], y: PARK[1] },
    { k: "rise", id },
  ];
}

function select(world, can) {
  const at = seatOf(can.place);
  return [{ k: "ext", e: 0 }, over(at)];
}

function tourNext(world) {
  const can = canById(world, "passkeys");
  if (can.place.at === "slot" && can.lit) return [{ k: "wait", s: 2.6 }, { k: "then", make: (w) => allow(w, can.id) }];
  if (can.place.at === "tube") return [{ k: "wait", s: 2.4 }, { k: "then", make: (w) => arrive(w, can.id) }];
  return [{ k: "wait", s: 1 }];
}

function enqueue(world, tasks) {
  const block = ++world.blocks;
  world.queue.push(...tasks.map((task) => ({ ...task, block })));
  return block;
}

function interrupt(world) {
  if (world.task && world.task.block === world.committed) {
    world.queue = world.queue.filter((task) => task.block === world.task.block);
    return;
  }
  world.task = null;
  world.queue = [];
}

const allowPending = (world) => [world.task, ...world.queue].some((task) => task && (task.k === "press" || (task.k === "then" && task.allow)));

const settle = (s, target, dt, seconds, calm) => {
  if (calm) {
    s.x = target;
    s.v = 0;
    return false;
  }
  const w = 1 / seconds;
  const h = dt / 4;
  for (let i = 0; i < 4; i++) {
    s.v += (w * w * (target - s.x) - 2 * w * s.v) * h;
    s.x += s.v * h;
  }
  if (Math.abs(target - s.x) < 0.01 && Math.abs(s.v) < 0.01) {
    s.x = target;
    s.v = 0;
    return false;
  }
  return true;
};

const LIFT_TIME = 1.5;
const easeIn = (t) => t * t;
const easeOut = (t) => 1 - (1 - t) * (1 - t);

function begin(world, task) {
  task.age = 0;
  if (task.k === "then") {
    world.queue.unshift(...task.make(world).map((t) => ({ ...t, block: task.block })));
    return;
  }
  if (task.k === "grab" || task.k === "press" || task.k === "drop") world.committed = task.block;
  if (task.k === "move") Object.assign(world.goal, { x: task.x, y: task.y });
  if (task.k === "ext") world.goal.e = task.e;
  if (task.k === "drop") {
    const can = canById(world, task.id);
    can.place = { at: "lift", tube: can.tube };
    can.z = L.hidden;
    can.lit = true;
    can.stamped = false;
  }
  if (task.k === "rise") {
    const can = canById(world, task.id);
    can.place = { at: "lift", tube: can.tube };
    can.z = L.cupSeat;
  }
  if (task.k === "grab") {
    const can = world.cans.find((c) => c.place.at === task.from.at && c.place.row === task.from.row && c.place.col === task.from.col && c.place.tube === task.from.tube);
    if (can) {
      can.place = { at: "held" };
      world.held = can.id;
    }
  }
  if (task.k === "put") {
    const can = canById(world, world.held);
    if (can) can.place = { ...task.to };
    world.held = null;
  }
  if (task.k === "press") {
    const can = canById(world, task.id);
    can.stamped = true;
    can.lit = false;
    world.press = 1;
  }
}

function run(world, task, dt, calm) {
  task.age += dt;
  if (task.k === "wait") return calm || task.age >= task.s;
  if (task.k === "drop" || task.k === "rise") {
    const can = canById(world, task.id);
    const t = calm ? 1 : Math.min(1, task.age / LIFT_TIME);
    if (task.k === "drop") can.z = L.hidden + (L.cupSeat - L.hidden) * easeOut(t);
    else can.z = L.cupSeat + (L.hidden - L.cupSeat) * easeIn(t);
    if (t < 1) return false;
    can.place = task.k === "drop" ? { at: "cup", tube: can.tube } : { at: "tube", tube: can.tube };
    return true;
  }
  const near = (s, target, d, v) => Math.abs(s.x - target) < d && Math.abs(s.v) < v;
  if (task.k === "move") return near(world.g.x, world.goal.x, 0.4, 3) && near(world.g.y, world.goal.y, 0.4, 3) && near(world.g.e, world.goal.e, 0.1, 2);
  if (task.k === "ext") return near(world.g.e, world.goal.e, 0.1, 2) && near(world.g.x, world.goal.x, 0.4, 3) && near(world.g.y, world.goal.y, 0.4, 3);
  return true;
}

const advance = (world, dt, calm) => {
  const x = settle(world.g.x, world.goal.x, dt, 0.26, calm);
  const y = settle(world.g.y, world.goal.y, dt, 0.26, calm);
  const e = settle(world.g.e, world.goal.e, dt, 0.115, calm);
  return x || y || e;
};

function step(world, dt, calm = false) {
  world.clock += dt;
  const moving = advance(world, dt, calm);
  world.press = calm ? 0 : Math.max(0, world.press - dt / 0.6);
  for (let guard = 0; guard < 64; guard++) {
    if (!world.task) {
      if (!world.queue.length) break;
      world.task = world.queue.shift();
      begin(world, world.task);
      if (calm) advance(world, 0, true);
    }
    if (!run(world, world.task, dt, calm)) break;
    world.task = null;
    dt = 0;
  }
  return moving || busy(world) || world.press > 0;
}

function readout(world, sessions = SESSIONS) {
  const waiting = waitingOf(world).length;
  return `${sessions.length} sessions · ${waiting} waiting · ≈ $${Math.round(costOf(sessions))} at API rates`;
}



function projector(P) {
  const a = (P.azimuth * Math.PI) / 180;
  const e = (P.elevation * Math.PI) / 180;
  const sinA = Math.sin(a);
  const cosA = Math.cos(a);
  const sinE = Math.sin(e);
  const cosE = Math.cos(e);
  const k = P.scale * Math.sqrt(1.6);
  const iso = ([x, y, z]) => [P.origin[0] + (x * sinA - y * cosA) * k, P.origin[1] + ((x * cosA + y * sinA) * sinE - z * cosE) * k];
  const along = ([x, y, z]) => [(x * sinA - y * cosA) * k, ((x * cosA + y * sinA) * sinE - z * cosE) * k];
  const depth = ([x, y, z]) => (x * cosA + y * sinA) * cosE + z * sinE;
  return { iso, along, depth };
}

function screenBox(box, iso) {
  if (!box) return null;
  let x0 = Infinity;
  let y0 = Infinity;
  let x1 = -Infinity;
  let y1 = -Infinity;
  for (let i = 0; i < 8; i++) {
    const [sx, sy] = iso([box[i & 1 ? 3 : 0], box[i & 2 ? 4 : 1], box[i & 4 ? 5 : 2]]);
    if (sx < x0) x0 = sx;
    if (sx > x1) x1 = sx;
    if (sy < y0) y0 = sy;
    if (sy > y1) y1 = sy;
  }
  return [x0, y0, x1, y1];
}

const EPS = 0.05;
const MARGIN = 0.3;
const overlaps = (a, b) => !!a && !!b && a[0] < b[2] - MARGIN && b[0] < a[2] - MARGIN && a[1] < b[3] - MARGIN && b[1] < a[3] - MARGIN;

function rel(a, b) {
  let behind = false;
  let front = false;
  for (let i = 0; i < 3; i++) {
    if (a[i + 3] <= b[i] + EPS) behind = true;
    if (b[i + 3] <= a[i] + EPS) front = true;
  }
  if (behind === front) return 0;
  return behind ? -1 : 1;
}

function orderScene(statics, edges, movers, depth) {
  const n = statics.length;
  const total = n + movers.length;
  const next = Array.from({ length: total }, () => []);
  const indeg = new Int32Array(total);
  const key = new Float64Array(total);
  const link = (a, b) => {
    next[a].push(b);
    indeg[b]++;
  };
  for (let i = 0; i < n; i++) key[i] = i;
  for (const [a, b] of edges) link(a, b);
  movers.forEach((m, index) => {
    const id = n + index;
    let lo = -1;
    for (let i = 0; i < n; i++) {
      const s = statics[i];
      if (!s.box || !overlaps(m.screen, s.screen)) continue;
      const r = rel(s.box, m.box);
      if (r < 0) {
        link(i, id);
        if (i > lo) lo = i;
      } else if (r > 0) link(id, i);
    }
    key[id] = lo + 0.5 + depth(m) * 1e-6;
  });
  for (let a = 0; a < movers.length; a++)
    for (let b = 0; b < movers.length; b++)
      if (a !== b && overlaps(movers[a].screen, movers[b].screen) && rel(movers[a].box, movers[b].box) < 0) link(n + a, n + b);
  const done = new Uint8Array(total);
  const order = [];
  for (let step = 0; step < total; step++) {
    let best = -1;
    for (let i = 0; i < total; i++) if (!done[i] && indeg[i] === 0 && (best < 0 || key[i] < key[best])) best = i;
    if (best < 0) break;
    done[best] = 1;
    order.push(best);
    for (const j of next[best]) indeg[j]--;
  }
  const conflicts = total - order.length;
  if (conflicts) for (const i of [...key.keys()].filter((i) => !done[i]).sort((a, b) => key[a] - key[b])) order.push(i);
  return { order, conflicts };
}

function moverBoxes(world, L) {
  const h = headAt(world);
  const bx = h.x - L.arm;
  const C = L.carriage;
  const B = L.beam;
  const Hd = L.head;
  const held = world.held && canById(world, world.held);
  const r = L.can.r;
  const cans = world.cans.map((can) => {
    if (can.place.at === "held" || can.place.at === "tube") return null;
    const [x, y, z] = canPosition(world, can);
    if (can.place.at === "lift" && z >= L.mouth - 0.01) return null;
    return [x - r, y - r, z, x + r, y + r, can.place.at === "lift" ? Math.min(z + L.can.h, L.mouth) : z + L.can.h];
  });
  return {
    bx,
    head: h,
    carriage: [bx - C.half, C.y0, C.z0, bx + C.half, C.y1, C.z1],
    beam: [bx - B.half, B.y0, B.z0, bx + B.half, B.y1 + 2.4, B.z1 + 0.6],
    headBlock: [bx + Hd.x0, h.y - Hd.half, Hd.gland, bx + Hd.x1, h.y + Hd.half, Hd.top],
    column: [h.x - r, h.y - r, h.pad - (held ? L.can.h : 0), h.x + r, h.y + r, Hd.gland],
    cans,
  };
}

const MD_NS = "http://www.w3.org/2000/svg";

function mdMount(host) {
  if (!host || host.__mdMounted) return null;
  host.__mdMounted = true;
  if (!document.getElementById("md-dispatch-css")) {
    const style = document.createElement("style");
    style.id = "md-dispatch-css";
    style.textContent = MD_CSS;
    document.head.appendChild(style);
  }
  host.classList.add("iso", "md-root");
  host.setAttribute("data-theme", "dark");
  host.innerHTML = MD_HTML;

  const { L, sessions } = MD_DATA;
  const { iso, along, depth } = projector(MD_DATA.P);
  const shift = (v) => {
    const [x, y] = along(v);
    return `translate(${x.toFixed(2)} ${y.toFixed(2)})`;
  };
  const stage = host.querySelector(".md-stage");
  const svg = stage.querySelector("svg");
  const scene = svg.querySelector("[data-scene]");
  const readoutEl = host.querySelector("[data-readout]");
  const status = host.querySelector("[data-status]");
  const still = matchMedia("(prefers-reduced-motion: reduce)");
  const statics = [...scene.children].map((el, i) => ({ el, box: MD_DATA.boxes[i], screen: screenBox(MD_DATA.boxes[i], iso) }));
  const keyEls = Object.fromEntries([...scene.querySelectorAll("[data-key]")].map((el) => [el.dataset.key, el]));

  const group = (html, attrs = {}) => {
    const g = document.createElementNS(MD_NS, "g");
    for (const [k, v] of Object.entries(attrs)) g.setAttribute(k, v);
    g.innerHTML = html;
    return g;
  };
  const carriage = { el: group(MD_PARTS.carriage, { "data-m": "carriage" }) };
  const beam = { el: group(MD_PARTS.beam, { "data-m": "beam" }) };
  const head = { el: group(MD_PARTS.head, { "data-m": "head" }) };
  const column = { el: group(`<g data-ext><g data-carry></g>${MD_PARTS.pad}</g><g clip-path="url(#mdx-rod)"><g data-ext>${MD_PARTS.rod}</g></g>`, { "data-m": "column" }) };
  const carry = column.el.querySelector("[data-carry]");
  carry.setAttribute("transform", shift([L.arm, 0, L.padRest - L.can.h]));
  const extEls = [...column.el.querySelectorAll("[data-ext]")];
  const world = createWorld();
  const cans = world.cans.map((can) => ({ can, el: group(MD_PARTS.can, { class: "md-can", "data-id": can.id }), held: false }));
  const movers = [carriage, beam, head, column, ...cans];

  let selected = null;
  let touring = !still.matches;
  let driving = false;
  let visible = false;
  let frame = 0;
  let last = 0;
  let idleTimer = 0;
  let order = "";
  let lastText = "";
  const keyDown = {};

  const sessionOf = (id) => sessions.find((s) => s.id === id);
  const rowOf = (can) => (can.lit ? "needs you" : can.place.at === "slot" ? ROW_NAMES[can.place.row] : "working");
  const describe = (can) => {
    const s = sessionOf(can.id);
    return `${AGENT_NAMES[s.agent]} · ${s.title} · ${rowOf(can)}${s.cost != null ? ` · $${s.cost < 1 ? s.cost.toFixed(2) : s.cost}` : ""}`;
  };
  const say = (text) => {
    if (status.textContent !== text) status.textContent = text;
  };

  function place() {
    const boxes = moverBoxes(world, L);
    const h = boxes.head;
    const armShift = shift([boxes.bx, 0, 0]);
    carriage.el.setAttribute("transform", armShift);
    beam.el.setAttribute("transform", armShift);
    const headShift = shift([boxes.bx, h.y, 0]);
    head.el.setAttribute("transform", headShift);
    column.el.setAttribute("transform", headShift);
    const down = shift([0, 0, -world.g.e.x]);
    for (const el of extEls) el.setAttribute("transform", down);
    carriage.box = boxes.carriage;
    beam.box = boxes.beam;
    head.box = boxes.headBlock;
    column.box = boxes.column;
    for (const c of cans) {
      const held = c.can.place.at === "held";
      if (held !== c.held) {
        c.held = held;
        if (held) {
          carry.appendChild(c.el);
          c.el.removeAttribute("transform");
        }
      }
      c.box = boxes.cans[world.cans.indexOf(c.can)];
      if (!held) {
        if (c.el.parentNode !== scene) scene.appendChild(c.el);
        if (c.box) c.el.setAttribute("transform", shift(canPosition(world, c.can)));
        c.el.toggleAttribute("data-lift-hidden", !c.box);
      }
      c.el.toggleAttribute("data-stamped", c.can.stamped && c.can.place.at !== "tube");
      c.el.toggleAttribute("data-sel", selected === c.can.id && driving);
      const lit = c.can.lit;
      if (c.lit !== lit) {
        c.lit = lit;
        c.el.querySelectorAll(".iso-solid").forEach((solid) => solid.toggleAttribute("data-lit", lit));
      }
    }
    for (const m of movers) m.screen = screenBox(m.box, iso);
    const active = movers.filter((m) => m.box && m.el.parentNode === scene);
    const centre = (m) => depth([(m.box[0] + m.box[3]) / 2, (m.box[1] + m.box[4]) / 2, (m.box[2] + m.box[5]) / 2]);
    const { order: ids } = orderScene(statics, MD_DATA.edges, active, centre);
    const signature = ids.join(",");
    if (signature !== order) {
      order = signature;
      const wanted = ids.map((id) => (id < statics.length ? statics[id].el : active[id - statics.length].el));
      for (const c of cans) if (!c.box && c.el.parentNode === scene) wanted.push(c.el);
      wanted.forEach((el, index) => {
        if (scene.children[index] !== el) scene.insertBefore(el, scene.children[index] ?? null);
      });
    }
  }

  function readout() {
    const can = selected && driving ? canById(world, selected) : null;
    const text = can && can.place.at === "slot" ? describe(can) : mdReadout(world, sessions);
    if (text !== lastText) {
      lastText = text;
      readoutEl.textContent = text;
    }
  }

  function keyVisual(name) {
    const el = keyEls[name];
    if (!el) return;
    keyDown[name] = still.matches ? 0.05 : name === "bell" ? 0.22 : 0.16;
    el.setAttribute("transform", shift([0, 0, name === "bell" ? -1.2 : -MD_DATA.keyTravel]));
    el.setAttribute("data-down", "");
    run();
  }

  function tick(now) {
    const dt = last ? Math.min((now - last) / 1000, 1 / 30) : 1 / 60;
    last = now;
    const calm = still.matches;
    if (touring && !busy(world)) enqueue(world, tourNext(world));
    const before = waitingOf(world).map((c) => c.id).join();
    const moving = step(world, dt, calm);
    const after = waitingOf(world).map((c) => c.id).join();
    if (before !== after) {
      const can = canById(world, "passkeys");
      if (after) keyVisual("bell");
      say(after ? `${describe(can)}: ${sessionOf(can.id).prompt}` : `Allowed. ${AGENT_NAMES[can.agent]} gets the answer back on its own line.`);
    }
    if (selected) {
      const can = canById(world, selected);
      if (can.place.at !== "slot") selected = null;
    }
    let keysMoving = false;
    for (const name of Object.keys(keyDown)) {
      if (keyDown[name] <= 0) continue;
      keyDown[name] -= dt;
      keysMoving = true;
      if (keyDown[name] <= 0) {
        keyEls[name].removeAttribute("transform");
        keyEls[name].removeAttribute("data-down");
      }
    }
    place();
    readout();
    frame = visible && (moving || touring || keysMoving || busy(world)) ? requestAnimationFrame(tick) : 0;
  }
  function run() {
    if (!frame && visible) {
      last = 0;
      frame = requestAnimationFrame(tick);
    }
  }
  function pause() {
    clearTimeout(idleTimer);
    if (touring) {
      touring = false;
      interrupt(world);
    }
  }
  function resumeLater(ms = 3600) {
    clearTimeout(idleTimer);
    idleTimer = setTimeout(() => {
      if (still.matches || stage.matches(":hover")) return;
      driving = false;
      touring = true;
      run();
    }, ms);
  }
  function takeOver() {
    pause();
    driving = true;
    resumeLater();
  }

  function selectStep(dir) {
    const list = slotsInUrgency(world);
    if (!list.length) return false;
    const index = selected ? list.findIndex((c) => c.id === selected) : -1;
    const next = index < 0 ? (dir > 0 ? 0 : list.length - 1) : index + dir;
    if (next < 0 || next >= list.length) return false;
    selected = list[next].id;
    enqueue(world, select(world, list[next]));
    say(describe(list[next]));
    return true;
  }
  function allowWaiting() {
    const waiting = waitingOf(world)[0];
    if (!waiting) {
      say("Nothing is waiting for you.");
      return;
    }
    if (allowPending(world)) return;
    selected = waiting.id;
    enqueue(world, [{ k: "then", allow: true, make: (w) => allow(w, waiting.id) }]);
  }

  stage.addEventListener("keydown", (event) => {
    if (event.key === "Tab" && !event.altKey && !event.metaKey && !event.ctrlKey) {
      takeOver();
      keyVisual("tab");
      if (selectStep(event.shiftKey ? -1 : 1)) event.preventDefault();
      else {
        selected = null;
        driving = false;
      }
      run();
      return;
    }
    if (event.key === "Enter" && !event.metaKey && !event.ctrlKey) {
      event.preventDefault();
      takeOver();
      if (event.altKey) keyVisual("opt");
      keyVisual("enter");
      allowWaiting();
      run();
    }
    if (event.key === "Alt") keyVisual("opt");
  });
  stage.addEventListener("pointerenter", () => {
    pause();
    run();
  });
  stage.addEventListener("pointerleave", () => resumeLater());
  stage.addEventListener("focus", () => {
    pause();
    say(readoutEl.textContent);
  });
  stage.addEventListener("blur", () => resumeLater());
  svg.addEventListener("click", (event) => {
    const key = event.target.closest("[data-key]");
    const canEl = event.target.closest(".md-can");
    if (key) {
      takeOver();
      keyVisual(key.dataset.key);
      if (key.dataset.key === "tab") selectStep(1) || ((selected = null), selectStep(1));
      else if (key.dataset.key !== "bell") allowWaiting();
    } else if (canEl) {
      const can = canById(world, canEl.dataset.id);
      if (can.place.at === "slot") {
        takeOver();
        selected = can.id;
        enqueue(world, select(world, can));
        say(describe(can));
      }
    } else return;
    stage.focus({ preventScroll: true });
    run();
  });
  still.addEventListener?.("change", () => {
    touring = !still.matches && !driving;
    run();
  });

  new IntersectionObserver(
    (entries) => {
      visible = entries[entries.length - 1].isIntersecting;
      if (visible) run();
      else if (frame) {
        cancelAnimationFrame(frame);
        frame = 0;
      }
    },
    { rootMargin: "120px 0px" },
  ).observe(stage);

  for (const m of movers) scene.appendChild(m.el);
  place();
  readout();
  return { world };
}

const mdReadout = readout;
export const mount = mdMount;
for (const el of document.querySelectorAll("#dispatch, [data-muster-dispatch]")) mdMount(el);

